# Stop systemd asking the Snapdragon watchdog for a timeout it cannot count.

system_conf_dir=${QUATTRO_QUALCOMM_SYSTEM_CONF_DIR:-/etc/systemd/system.conf.d}

if quattro-hw-aarch64-qualcomm; then
  mkdir -p "$system_conf_dir"
  cat >"$system_conf_dir/60-quattro-qualcomm-reboot-watchdog.conf" <<'CONF'
# Generated by Quattro for Qualcomm Snapdragon devices.
# systemd-shutdown arms the hardware watchdog for RebootWatchdogSec, ten minutes
# by default, but qcom_wdt counts to 32 seconds at most. The kernel refuses the
# timeout, systemd leaves the watchdog disarmed and prints "Failed to set
# watchdog hardware timeout to 10min: Invalid argument" at every shutdown.
# Turn it off, which is what already happens, without the error. A timeout the
# watchdog can count would reset a shutdown still syncing after 30 seconds.
[Manager]
RebootWatchdogSec=off
CONF
fi
